#!/usr/bin/env python3
"""Generate source-only reference-gate groups from pinned checked source snapshots."""
import hashlib,json,re,sys
from pathlib import Path
if not sys.flags.isolated or not sys.flags.no_site or sys.flags.optimize:raise SystemExit('use python3 -I -S -B')
P=Path(__file__).resolve().parent;D=P.parents[1];A=D/'research/nine-sharing-seed38-weighted-retry/src/DiophantineConsistency/NormAssignment38.lean';R=D/'research/nine-sharing-norm38-reference-base-retry02/src/DiophantineConsistency/Norm38ReferenceBase.lean';sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def need(v,s):
 if not v:raise RuntimeError(s)
need(sha(A)=='c66694acbba431aa20f4be03a85c0210d24f1b3a51378e0bbeb40452b611817a' and sha(R)=='be7f61985d51b07cfda37da0d1ca40c7d44a01950ef6cf94866a5cb3e2bf1da2','source pins')
gates=[(int(t),int(l),int(r),o) for t,l,r,o in re.findall(r'    ⟨(\d+), (\d+), (\d+), GateOp\.(add|sub|mul)⟩',A.read_text())];need(len(gates)==60 and [g[0] for g in gates]==list(range(21,81)),'gate order');defs=dict((int(i),v) for i,v in re.findall(r'^  let a(\d+) : R := (.+)$',R.read_text(),re.M));need(len(defs)==81,'reference nodes');signs={'add':'+','sub':'-','mul':'*'}
for t,l,r,o in gates:need(defs[t]==f'a{l} {signs[o]} a{r}',f'graph/reference node {t}')
header='''import DiophantineConsistency.Norm38ReferenceBase\n\n/-! Source-only proposed bounded reference-gate group; unchecked Lean. -/\nset_option autoImplicit false\nset_option maxHeartbeats 4000000\nset_option maxRecDepth 4096\nnoncomputable section\nnamespace DiophantineConsistency.Norm38Reference\nopen SharingGateModel\n\n''';files=[]
for group in range(12):
 s=header
 for t,l,r,o in gates[group*5:group*5+5]:s+=f'''theorem reference_gate{t} {{R : Type*}} [CommRing R] (p : Fin 4 → R) (x : Fin 14 → R) :\n    reference p x {t} = ringCompute GateOp.{o} (reference p x {l}) (reference p x {r}) := by rfl\n\n'''
 s+='end DiophantineConsistency.Norm38Reference\n';path=P/'src/DiophantineConsistency'/f'Norm38ReferenceGateGroup{group:02}.lean';path.write_text(s);files.append({'module':f'DiophantineConsistency.Norm38ReferenceGateGroup{group:02}','source_sha256':sha(path),'gates':[x[0] for x in gates[group*5:group*5+5]]})
imports=''.join(f'import DiophantineConsistency.Norm38ReferenceGateGroup{g:02}\n' for g in range(12));s=imports+'''\n/-! Proposed gate-equation assembly; unchecked Lean. -/\nset_option autoImplicit false\nset_option maxHeartbeats 4000000\nset_option maxRecDepth 4096\nnoncomputable section\nnamespace DiophantineConsistency.Norm38Reference\nopen SharingGateModel\n\ntheorem reference_gate_equations_batched {R : Type*} [CommRing R]\n    (p : Fin 4 → R) (x : Fin 14 → R) :\n    ∀ g ∈ NormAssignment38.gates,\n      reference p x g.target = ringCompute g.op (reference p x g.left) (reference p x g.right) := by\n  simp only [NormAssignment38.gates, List.mem_cons, List.not_mem_nil, forall_eq_or_imp,\n    false_implies, forall_const, and_true]\n  exact ⟨'''+',\n    '.join(f'reference_gate{t} p x' for t,_,_,_ in gates)+''', by simp⟩\n\nend DiophantineConsistency.Norm38Reference\n#print axioms DiophantineConsistency.Norm38Reference.reference_gate_equations_batched\n''';path=P/'src/DiophantineConsistency/Norm38ReferenceGatesAll.lean';path.write_text(s);files.append({'module':'DiophantineConsistency.Norm38ReferenceGatesAll','source_sha256':sha(path),'gates':[]});(P/'source-manifest.json').write_text(json.dumps({'scope':'Source generation only; no Lean proof.','rows':files},sort_keys=True,indent=2)+'\n');print(json.dumps({'status':'PASS_SOURCE_GENERATION_ONLY','reference_sha256':sha(R),'assignment_sha256':sha(A),'gates':len(gates),'groups':12,'scope':'Every reference node matches the corresponding gate syntactically. Generated rfl/assembly proofs are uncompiled.'},sort_keys=True,indent=2))
